@import 'tailwindcss';

@theme {
  --color-canvas: #f5f7fc;
  --color-paper: #fff;
  --color-context: #eaf0ff;
  --color-ink: #15243b;
  --color-secondary: #344763;
  --color-muted: #405575;
  --color-action: #2e6df6;
  --color-action-hover: #215bcc;
  --color-link: #1748af;
  --color-control: #586d91;
  --color-divider: #ccd8ee;
  --color-focus: #1746b4;
  --color-error: #9e2f26;
  --color-error-tint: #fff2ef;
  --font-heading: Georgia, 'Times New Roman', serif;
  --font-interface: Arial, system-ui, sans-serif;
}

@layer base {
  html {
    scroll-padding-block: 1.5rem;
  }
  body {
    @apply min-h-screen bg-canvas font-interface text-ink;
  }
  h1,
  h2 {
    @apply font-heading font-normal;
  }
  h1 {
    font-size: clamp(2rem, 5vw, 3rem);
    line-height: 1.15;
    text-wrap: balance;
  }
  h2 {
    @apply text-[1.75rem] leading-tight;
  }
  :focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
  }
  [tabindex='-1']:focus:not(:focus-visible) {
    outline: none;
  }
}

@layer components {
  .shell {
    width: min(100% - 2.5rem, 68rem);
    margin-inline: auto;
  }
  .skip-link {
    position: absolute;
    inset-block-start: 0.75rem;
    inset-inline-start: 0.75rem;
    z-index: 1;
    transform: translateY(calc(-100% - 1rem));
    @apply rounded bg-paper px-4 py-3 font-bold text-link;
  }
  .skip-link:focus {
    transform: translateY(0);
  }
  .site-header {
    @apply border-b border-divider bg-paper;
  }
  .brand {
    @apply flex min-h-[3.875rem] items-center gap-2.5 text-base font-bold sm:min-h-[4.6875rem] sm:text-[1.1875rem];
  }
  .brand img,
  .country-choice img {
    color: var(--color-link);
  }
  .wizard {
    width: min(100% - 2.5rem, 58rem);
    margin-inline: auto;
    padding-block-end: 4rem;
  }
  .wizard-progress {
    @apply flex flex-wrap items-center gap-x-3 gap-y-2 border-b border-divider py-4 sm:gap-x-6;
    list-style: none;
    margin: 0;
  }
  .wizard-progress li {
    @apply flex items-center gap-1.5 text-sm text-muted sm:gap-2;
  }
  .wizard-progress .current {
    @apply font-bold text-ink;
  }
  .step-number {
    @apply inline-grid size-[1.375rem] place-items-center rounded-full border border-control text-xs font-bold;
  }
  .wizard-progress .current .step-number {
    @apply border-action bg-action text-white;
  }
  .wizard-progress .completed .step-number {
    @apply border-link bg-link text-white;
  }
  .step-heading {
    margin-block: 1.5rem 0.875rem;
  }
  .step-heading p {
    @apply mt-2 text-base text-secondary;
  }
  .details {
    max-width: 44.5rem;
    margin-inline: auto;
  }
  .required-note {
    @apply mb-3 text-sm font-bold text-muted;
  }
  .form-grid {
    @apply grid grid-cols-1 gap-x-6 gap-y-5;
  }
  .field {
    @apply min-w-0;
  }
  .field label {
    overflow-wrap: anywhere;
  }
  .field > label {
    @apply mb-2 block text-sm font-bold;
  }
  .field input:not([type='checkbox']),
  .field select {
    @apply min-h-11 w-full min-w-0 rounded-md border border-control bg-paper px-3 text-base text-ink;
  }
  .field select:has(option:checked:disabled) {
    @apply text-muted;
  }
  .field input[type='checkbox'] {
    @apply size-5 shrink-0 accent-link;
  }
  .checkbox-row {
    @apply flex min-h-11 items-center gap-3;
  }
  .checkbox-row label {
    @apply flex min-h-11 min-w-0 items-center text-base;
  }
  .field-help {
    @apply mt-1.5 text-sm leading-5 text-muted;
    overflow-wrap: anywhere;
  }
  .field-error {
    @apply mt-1.5 flex items-start gap-1.5 text-sm font-bold leading-5 text-error;
    overflow-wrap: anywhere;
  }
  .field-error img {
    @apply mt-[2px] shrink-0;
  }
  .field.has-error :is(input, select) {
    border-color: var(--color-error);
    box-shadow: inset 0 0 0 1px var(--color-error);
  }
  .form-actions {
    @apply mt-7 flex border-t border-divider pt-5;
  }
  .primary-button {
    @apply inline-flex min-h-12 items-center justify-center rounded-md bg-action px-6 text-base font-bold text-white;
    transition: background-color 120ms;
  }
  .primary-button:is(:hover, :active) {
    @apply bg-action-hover;
  }
  .form-actions .primary-button {
    @apply w-full;
  }
  .return-note {
    @apply mt-4 text-sm text-muted lg:hidden;
  }
  .status-panel {
    width: min(100%, 44.5rem);
    margin-inline: auto;
    @apply rounded-lg border border-divider bg-paper px-4 py-5 sm:px-6;
  }
  .status-panel p,
  .status-panel [role='status'] {
    @apply mt-2 text-sm text-secondary;
  }
  .status-panel button {
    @apply mt-4;
  }
  .error-panel {
    @apply border-error bg-error-tint text-error;
  }
  .error-panel p,
  .error-panel [role='status'] {
    @apply text-error;
  }
  .placeholder {
    @apply mt-5 h-3 rounded bg-context;
  }
  .placeholder.short {
    @apply mt-2 w-3/5;
  }
  .handoff {
    margin-block-start: 2.25rem;
  }
  .text-link {
    @apply inline-flex min-h-11 items-center font-bold text-link underline underline-offset-4;
  }
  .handoff .text-link {
    @apply mt-2;
  }
  .picker {
    @apply grid gap-6 py-10;
  }
  .picker-intro {
    @apply self-center;
  }
  .picker-intro p {
    @apply mt-3 text-base text-secondary;
  }
  .accent-line {
    @apply mb-4 h-px w-11 bg-link;
  }
  .country-choices {
    @apply grid gap-3;
  }
  .country-choice {
    @apply flex min-h-[4.5rem] min-w-0 items-center gap-3 rounded-md border border-control bg-paper px-4 py-3 font-heading text-xl;
  }
  .country-choice:hover {
    @apply bg-context;
  }
  .country-choice img {
    @apply ml-auto shrink-0;
  }
  .country-code {
    @apply rounded bg-context px-2 py-2 font-interface text-sm font-bold text-link;
  }
  .route-error {
    @apply w-full;
  }
  .route-error p {
    @apply mt-0;
  }
  .picker-footer {
    @apply border-t border-divider pt-3 text-sm text-muted;
  }

  @media (min-width: 48rem) {
    .form-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .check-field {
      grid-column: 1 / -1;
    }
    .form-actions {
      justify-content: flex-end;
    }
    .form-actions .primary-button {
      width: 10rem;
    }
  }

  @media (min-width: 64rem) {
    .wizard-progress {
      min-height: 3.625rem;
      justify-content: center;
    }
    .wizard-progress li:not(:last-child)::after {
      content: '';
      display: block;
      width: 3.5rem;
      height: 1px;
      margin-inline-start: 1rem;
      background: var(--color-divider);
    }
    .step-heading {
      text-align: center;
      margin-block: 1rem;
    }
    .form-grid {
      row-gap: 2rem;
    }
    .picker {
      grid-template-columns: 1fr 0.85fr;
      gap: 2rem 5rem;
      padding-block-start: 8rem;
    }
    .picker-footer {
      grid-column: 1 / -1;
      margin-block-start: 5rem;
    }
    .handoff {
      text-align: center;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .primary-button {
      transition: none;
    }
  }
}
