  --color-ink: #15243b;
  --color-secondary: #344763;
  --color-muted: #405575;
  --color-action: #2e6df6;
  --color-action-hover: #215bcc;
  --color-link: #1748af;
  --color-control: #586d91;
  --color-divider: #ccd8ee;
  --color-focus: #1746b4;
  --color-error: #9e2f26;
  --color-error-tint: #fff2ef;
  --font-heading: Georgia, 'Times New Roman', serif;
