  .handoff .text-link {
    @apply mt-2;
  }
  .picker {
    @apply grid gap-6 py-10;
  }
  .picker-intro {
    @apply self-center;
  }
  .picker-intro p {
    @apply mt-3 text-base text-secondary;
  }
  .accent-line {
    @apply mb-4 h-px w-11 bg-link;
  }
  .country-choices {
    @apply grid gap-3;
  }
  .country-choice {
    @apply flex min-h-[4.5rem] min-w-0 items-center gap-3 rounded-md border border-control bg-paper px-4 py-3 font-heading text-xl;
  }
  .country-choice:hover {
    @apply bg-context;
  }
  .country-choice img {
    @apply ml-auto shrink-0;
  }
  .country-code {
    @apply rounded bg-context px-2 py-2 font-interface text-sm font-bold text-link;
  }
  .route-error {
    @apply w-full;
  }
  .route-error p {
    @apply mt-0;
  }
  .picker-footer {
    @apply border-t border-divider pt-3 text-sm text-muted;
  }

  @media (min-width: 48rem) {
    .form-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .check-field {
      grid-column: 1 / -1;
