    }
    .picker-footer {
      grid-column: 1 / -1;
      margin-block-start: 5rem;
    }
    .handoff {
      text-align: center;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .primary-button {
      transition: none;
    }
  }
