  }
  .route-error p {
    @apply mt-0;
  }
  .picker-footer {
    @apply border-t border-divider pt-3 text-sm text-muted;
  }

  @media (min-width: 48rem) {
    .form-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .check-field {
      grid-column: 1 / -1;
    }
    .form-actions {
      justify-content: flex-end;
    }
    .form-actions .primary-button {
      width: 10rem;
    }
  }

  @media (min-width: 64rem) {
    .wizard-progress {
      min-height: 3.625rem;
      justify-content: center;
    }
    .wizard-progress li:not(:last-child)::after {
      content: '';
      display: block;
      width: 3.5rem;
